import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"移动应用","description":"Android 侧载按单文件发布。F-Droid 是 listing。不能代替 App Store / Play 上架审核。","frontmatter":{"title":"移动应用","description":"Android 侧载按单文件发布。F-Droid 是 listing。不能代替 App Store / Play 上架审核。"},"headers":[],"relativePath":"guide/scenarios/mobile.md","filePath":"guide/scenarios/mobile.md","lastUpdated":1790057721000}`),a={name:`guide/scenarios/mobile.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="移动应用" tabindex="-1">移动应用 <a class="header-anchor" href="#移动应用" aria-label="Permalink to “移动应用”">​</a></h1><h2 id="产物形态" tabindex="-1">产物形态 <a class="header-anchor" href="#产物形态" aria-label="Permalink to “产物形态”">​</a></h2><p>Android <strong>侧载</strong>把 APK 当<strong>单个文件</strong>发布（平台矩阵单文件）。官方 SDK 不是 APK 安装器：须自备 Replacer。比较与下载仍是 <strong>POST</strong> check + SHA-256 对象。</p><p>F-Droid 订阅是另一条商店 listing（<code>fdroid</code>），与原生 JSON <strong>不是</strong>同一 URL。索引文档：</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-12" id="tab-13" checked><label data-title="index-v1" for="tab-13">index-v1</label><input type="radio" name="group-12" id="tab-14"><label data-title="index-v2" for="tab-14">index-v2</label></div><div class="blocks"><div class="language-text active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://updates.example.com/api/v1/projects/myapp/store/fdroid/stable/index-v1.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://updates.example.com/api/v1/projects/myapp/store/fdroid/stable/index-v2.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><p>控制台：<strong>设置 → 商店协议</strong> → <strong>新建上架</strong>，协议 <code>fdroid</code>。未知路径（例如 <code>index.xml</code>）纯文本 404。官方 SDK <strong>不</strong>读 F-Droid 索引。</p><p>iPhone 企业签 / 侧载可以走原生 JSON 或自定义分发，<strong>不能</strong>代替 App Store 审核。Play / App Store 私有协议不在本产品范围。</p><h2 id="故障" tabindex="-1">故障 <a class="header-anchor" href="#故障" aria-label="Permalink to “故障”">​</a></h2><p>缺 listing → 纯文本 404。原生 check 失败码见 <a href="/faq/errors">FAQ · 失败代码</a>。</p><p>相关：<a href="/guide/features/store">商店订阅</a>、<a href="./desktop">桌面应用</a>。</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};